#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n; placed++){
        // Find where (placed+1) is
        int pos = -1;
        for(int i = placed; i < n; i++){
            if(p[i] == placed + 1){ pos = i; break; }
        }
        if(pos == placed) continue; // already in place

        // Step 1: Move element from pos to position 0
        // Use x=pos, y=n-pos (suffix includes element at pos)
        // But x+y = pos + (n-pos) = n, need x+y < n. So use y = n-pos, x = pos, but that's n.
        // Instead: x = pos, y = n - pos. x+y=n not < n.
        // Use: x=1, y=n-pos. Then x+y = 1+n-pos = n-pos+1. Need < n => pos > 1... not always.
        // Better: make element go to front. suffix = p[pos..n-1], x can be anything from 1..pos-1 (if pos>=2)
        // Actually simplest: x=pos, y=n-pos doesn't work. Let's try x=pos, y=n-pos-1 if n-pos-1>0 and pos>0 and pos+n-pos-1<n (=n-1<n, yes)

        if(pos > 0 && pos < n-1){
            // x=pos, y=n-1-pos: suffix=p[pos+1..n-1], element at pos stays in middle start
            // That puts element at position n-1-pos (after suffix of size n-1-pos, element is at start of middle... no)
            // Let me think: result = p[pos+1..n-1] + p[pos..pos] + p[0..pos-1] -- wait y=n-1-pos
            // suffix = p[n-y..n-1] = p[pos+1..n-1], middle = p[x..n-y-1] = p[pos..pos], prefix = p[0..pos-1]
            // result: suffix + middle + prefix = p[pos+1..n-1] + [p[pos]] + p[0..pos-1]
            // element p[pos] is now at position n-1-pos. Not helpful directly.

            // To get element to position 0: make it part of suffix start.
            // y = n - pos, but x + y < n => x < pos. Use x = max(1, placed) or x=1 if placed=0
            int x1 = max(1, placed);
            int y1 = n - pos;
            if(x1 > 0 && y1 > 0 && x1 + y1 < n){
                ops.push_back({x1, y1});
                apply(p, x1, y1);
                pos = pos - x1; // element was at pos, prefix of x1 removed from front, suffix of y1 moved to front. Element is at position 0 in suffix.
                // Actually element at index pos, suffix starts at n-y1=pos. So element is at start of suffix -> goes to position 0.
                placed--; // redo this position
                placed++;
                // Now element is at position 0. Move to 'placed'.
                int pos2 = 0;
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos2=i;break;}
                if(pos2 == placed) continue;
                int x2 = pos2 + 1; // prefix includes element
                int y2 = n - placed - 1; // need result to put element at 'placed'
                // result = suffix(y2) + middle + prefix(x2). Element in prefix goes to end - but we want it at 'placed'
                // prefix at end starts at n - x2. Element at pos2 in prefix goes to n - x2 + pos2.
                // We want n - x2 + pos2 = placed => n - (pos2+1) + pos2 = n - 1 != placed generally.
                // Different approach: x2 = 1 (just element 0), y2 = n - placed - 1
                if(pos2 == 0 && placed < n-1){
                    x2 = 1; y2 = n - placed - 1;
                    if(x2+y2<n && y2>0){
                        ops.push_back({x2,y2});
                        apply(p,x2,y2);
                        continue;
                    }
                }
            }
        }
        // Fallback: just try all valid (x,y) to place element
        // brute force best single op
        bool found = false;
        for(int x=1;x<n && !found;x++) for(int y=1;x+y<n && !found;y++){
            vector<int> tmp = p;
            apply(tmp,x,y);
            if(tmp[placed]==placed+1){
                ops.push_back({x,y});
                p=tmp;
                found=true;
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
